<script setup>
import { computed, inject, ref, watch } from 'vue'
import { objectWrite } from '../../data-object-api.js'
import { ElMessage } from 'element-plus'
import DictionaryPicker from './DictionaryPicker.vue'
const can=inject('canPermission',()=>false),dictionaryOpen=ref(false)
function addDictionary({fields:chosen,missingLength}){if(fields.value.length===1&&!fields.value[0].name.trim())fields.value=[];fields.value.push(...chosen);if(missingLength.length)ElMessage.warning(`请补填字段长度：${missingLength.join('、')}`)}
const props=defineProps({modelValue:Boolean,sources:Array,directories:Array,selectedDirectory:Number,copyFrom:Object})
const emit=defineEmits(['update:modelValue','created'])
const sourceId=ref(null),directoryId=ref(null),catalog=ref(''),schema=ref(''),table=ref(''),name=ref(''),description=ref(''),fields=ref([]),preview=ref(null),busy=ref(false),error=ref('')
const source=computed(()=>props.sources.find(s=>s.id===sourceId.value))
const types=computed(()=>source.value?.type==='MYSQL'?['VARCHAR','CHAR','INT','BIGINT','DECIMAL','DATE','DATETIME']:source.value?.type==='POSTGRESQL'?['VARCHAR','CHAR','INTEGER','BIGINT','NUMERIC','DATE','TIMESTAMP']:source.value?.type==='ORACLE'?['VARCHAR2','CHAR','NUMBER','DATE','TIMESTAMP']:[])
function emptyField(){return {name:'',type:types.value[0]||'',length:null,scale:null,nullable:true,primaryKey:false,remarks:''}}
watch(()=>props.modelValue,open=>{if(open){sourceId.value=null;directoryId.value=props.selectedDirectory||null;catalog.value='';schema.value='';table.value='';name.value='';description.value='';fields.value=[];preview.value=null;error.value=''}})
function sourceChanged(){catalog.value=source.value?.type==='ORACLE'?'':source.value?.database||'';schema.value=source.value?.type==='POSTGRESQL'?'public':source.value?.type==='ORACLE'?source.value?.username?.toUpperCase()||'':'';fields.value=props.copyFrom?.fields?.map(f=>{const t=f.type.toUpperCase();return {name:f.name,type:t,length:['VARCHAR','VARCHAR2','CHAR','DECIMAL','NUMERIC','NUMBER'].includes(t)?f.length:null,scale:['DECIMAL','NUMERIC','NUMBER'].includes(t)?f.scale:null,nullable:f.nullable==='YES',primaryKey:f.primaryKey==='YES',remarks:f.remarks||''}})||[emptyField()];preview.value=null}
async function createPreview(){try{busy.value=true;error.value='';const identity={sourceId:sourceId.value,catalog:catalog.value||null,schema:schema.value||null,table:table.value.trim(),type:'TABLE'};preview.value=await objectWrite('/api/data-object-operations/create-preview','POST',{directoryId:directoryId.value,identity,name:name.value.trim(),description:description.value.trim(),fields:fields.value})}catch(e){error.value=e.message}finally{busy.value=false}}
async function execute(){if(!preview.value)return;try{busy.value=true;error.value='';preview.value=await objectWrite(`/api/data-object-operations/${preview.value.operationId}/execute`,'POST',{});if(preview.value.status==='SUCCEEDED')emit('created')}catch(e){error.value=e.message}finally{busy.value=false}}
async function cancelPreview(){if(!preview.value||preview.value.status!=='PREPARED')return;try{await objectWrite(`/api/data-object-operations/${preview.value.operationId}`,'DELETE');preview.value=null}catch(e){error.value=e.message}}
</script>
<template><el-dialog :model-value="modelValue" title="新增数据对象" width="min(1000px,96vw)" :close-on-click-modal="false" :close-on-press-escape="false" :show-close="preview?.status !== 'PREPARED'" @update:model-value="emit('update:modelValue',$event)"><el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''"/><template v-if="!preview"><el-form label-position="top"><div class="grid"><el-form-item label="数据源" required><el-select v-model="sourceId" @change="sourceChanged"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="对象目录" required><el-select v-model="directoryId"><el-option v-for="d in directories" :key="d.id" :label="d.label" :value="d.id"/></el-select></el-form-item><el-form-item label="数据库 / catalog"><el-input v-model="catalog"/></el-form-item><el-form-item label="模式 / schema"><el-input v-model="schema"/></el-form-item><el-form-item label="物理表名" required><el-input v-model="table"/></el-form-item><el-form-item label="对象中文名" required><el-input v-model="name" maxlength="200"/></el-form-item></div><el-form-item label="描述"><el-input v-model="description" type="textarea" maxlength="1000"/></el-form-item></el-form><div class="heading"><b>字段定义</b><div class="field-actions"><el-button v-if="can('datasource.dictionary.read')" class="dictionary-action" :disabled="!source" @click="dictionaryOpen=true"><svg class="field-action-icon" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 4.3C6.6 3.2 4.7 3 2.2 3.5v8.1c2.5-.5 4.4-.3 5.8.8 1.4-1.1 3.3-1.3 5.8-.8V3.5c-2.5-.5-4.4-.3-5.8.8ZM8 4.3v8.1"/></svg><span>从字典选择</span></el-button><el-button class="add-field-action" :disabled="!source" @click="fields.push(emptyField())"><svg class="field-action-icon" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3.3v9.4M3.3 8h9.4"/></svg><span>添加字段</span></el-button></div></div><el-table :data="fields" max-height="320"><el-table-column label="字段名" min-width="130"><template #default="s"><el-input v-model="s.row.name"/></template></el-table-column><el-table-column label="类型" min-width="120"><template #default="s"><el-select v-model="s.row.type"><el-option v-if="s.row.type&&!types.includes(s.row.type)" :value="s.row.type" :label="s.row.type+'（不支持，请选择其他类型）'" disabled/><el-option v-for="t in types" :key="t" :value="t" :label="t"/></el-select></template></el-table-column><el-table-column label="长度" width="110"><template #default="s"><el-input-number v-model="s.row.length" :controls="false" :min="1"/></template></el-table-column><el-table-column label="精度" width="100"><template #default="s"><el-input-number v-model="s.row.scale" :controls="false" :min="0"/></template></el-table-column><el-table-column label="可空" width="70"><template #default="s"><el-checkbox v-model="s.row.nullable" :disabled="s.row.primaryKey"/></template></el-table-column><el-table-column label="主键" width="70"><template #default="s"><el-checkbox v-model="s.row.primaryKey"/></template></el-table-column><el-table-column label="注释" min-width="160"><template #default="s"><el-input v-model="s.row.remarks" maxlength="1000"/></template></el-table-column><el-table-column label="操作" width="80"><template #default="s"><el-button link type="danger" @click="fields.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table></template><template v-else><el-alert :title="preview.status==='PREPARED'?'请核对目标和建表语句，确认后将在目标数据库创建物理表。':`操作状态：${preview.status}`" :type="preview.status==='SUCCEEDED'?'success':'warning'" :closable="false"/><p>目标：{{ source?.name }} / {{ preview.identity.catalog || '—' }} / {{ preview.identity.schema || '—' }} / {{ preview.identity.table }}</p><pre>{{ preview.sql }}</pre><p v-if="['UNKNOWN','NEEDS_REGISTRATION'].includes(preview.status)">物理表可能已创建，请在操作记录中核对并重新登记，不要重复建表。</p></template><template #footer><el-button v-if="!preview || preview.status!=='PREPARED'" @click="emit('update:modelValue',false)">关闭</el-button><el-button v-if="preview?.status==='PREPARED'" :disabled="busy" @click="cancelPreview">返回编辑</el-button><el-button v-if="!preview" type="primary" :loading="busy" @click="createPreview">预览建表</el-button><el-button v-else-if="preview.status==='PREPARED'" type="primary" :loading="busy" @click="execute">确认建表</el-button></template></el-dialog><DictionaryPicker v-model="dictionaryOpen" :source-type="source?.type" :existing="fields" @select="addDictionary"/></template>
<style scoped>.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.grid .el-select{width:100%}.heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:20px 0 10px}.field-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}.field-actions :deep(.el-button){height:32px;min-height:32px;margin:0;padding:0 11px;border-radius:4px;font-size:13px;color:#405a76;border-color:#ccd9e5}.field-actions :deep(.el-button > span){display:inline-flex;align-items:center;gap:6px}.field-actions :deep(.dictionary-action:not(.is-disabled)){background:#f4f8fd;color:#3578b8;border-color:#c8dcef}.field-actions :deep(.el-button:not(.is-disabled):hover){border-color:#7fb2e4;color:#287bc7}.field-actions :deep(.el-button.is-disabled){color:#a8abb2;border-color:#e4e7ed;background:#f5f7fa}.field-action-icon{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;flex:none}.el-input-number{width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7fa;padding:12px}@media(max-width:700px){.grid{grid-template-columns:1fr}.heading{flex-wrap:wrap}.field-actions{margin-left:auto}}</style>
